import { Avatar, Button, IconButton, Paper, Stack, Typography, useTheme, TextField, useMediaQuery } from '@mui/material'
import ContentCopyIcon from '@mui/icons-material/ContentCopy'
import EditIcon from '@mui/icons-material/Edit'
import SecurityIcon from '@mui/icons-material/Security'
import React, { useEffect, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { selectUserInfo, fetchLoggedInUserByIdAsync, updateUserByIdAsync, selectUserStatus } from '../UserSlice'
import { addAddressAsync, resetAddressAddStatus, resetAddressDeleteStatus, resetAddressUpdateStatus, selectAddressAddStatus, selectAddressDeleteStatus, selectAddressStatus, selectAddressUpdateStatus, selectAddresses } from '../../address/AddressSlice'
import { Address } from '../../address/components/Address'
import { useForm } from 'react-hook-form'
import { LoadingButton } from '@mui/lab'
import { toast } from 'react-toastify'
import { enable2FAAsync, confirm2FAAsync, disable2FAAsync, selectEnable2FAStatus, selectConfirm2FAStatus, selectDisable2FAStatus, selectEnable2FAError, selectConfirm2FAError, selectDisable2FAError, resetEnable2FAStatus, resetConfirm2FAStatus, resetDisable2FAStatus, checkAuthAsync } from '../../auth/AuthSlice'
import { useTranslation } from 'react-i18next'

export const UserProfile = () => {

    const dispatch = useDispatch()
    const { register, handleSubmit, reset } = useForm()
    const status = useSelector(selectAddressStatus)
    const userInfo = useSelector(selectUserInfo)
    const addresses = useSelector(selectAddresses)
    const theme = useTheme()
    const [addAddress, setAddAddress] = useState(false)
    const [show2FAConfirm, setShow2FAConfirm] = useState(false)
    const [isEdit, setIsEdit] = useState(false)

    const addressAddStatus = useSelector(selectAddressAddStatus)
    const addressUpdateStatus = useSelector(selectAddressUpdateStatus)
    const addressDeleteStatus = useSelector(selectAddressDeleteStatus)
    const userUpdateStatus = useSelector(selectUserStatus)

    const is900 = useMediaQuery(theme.breakpoints.down(900))
    const is480 = useMediaQuery(theme.breakpoints.down(480))
    const { t } = useTranslation()

    const enable2FAStatus = useSelector(selectEnable2FAStatus)
    const confirm2FAStatus = useSelector(selectConfirm2FAStatus)
    const disable2FAStatus = useSelector(selectDisable2FAStatus)
    const enable2FAError = useSelector(selectEnable2FAError)
    const confirm2FAError = useSelector(selectConfirm2FAError)
    const disable2FAError = useSelector(selectDisable2FAError)

    const { register: registerEdit, handleSubmit: handleSubmitEdit, reset: resetEdit } = useForm()

    useEffect(() => {
        window.scrollTo({
            top: 0,
            behavior: "instant"
        })
    }, [])


    useEffect(() => {
        if (addressAddStatus === 'fulfilled') {
            toast.success(t('auth.addresses.toastAddSuccess'))
        }
        else if (addressAddStatus === 'rejected') {
            toast.error(t('auth.addresses.toastAddError'))
        }
    }, [addressAddStatus, t])

    useEffect(() => {
        if (addressUpdateStatus === 'fulfilled') {
            toast.success(t('auth.addresses.toastUpdateSuccess'))
        }
        else if (addressUpdateStatus === 'rejected') {
            toast.error(t('auth.addresses.toastUpdateError'))
        }
    }, [addressUpdateStatus, t])

    useEffect(() => {
        if (addressDeleteStatus === 'fulfilled') {
            toast.success(t('auth.addresses.toastDeleteSuccess'))
        }
        else if (addressDeleteStatus === 'rejected') {
            toast.error(t('auth.addresses.toastDeleteError'))
        }
    }, [addressDeleteStatus, t])

    useEffect(() => {
        if (userUpdateStatus === 'fulfilled' && isEdit) {
            toast.success(t('auth.profile.updateSuccess'))
            setIsEdit(false)
        }
        else if (userUpdateStatus === 'rejected' && isEdit) {
            toast.error(t('auth.profile.updateError'))
        }
    }, [userUpdateStatus, isEdit, t])

    useEffect(() => {
        return () => {
            dispatch(resetAddressAddStatus())
            dispatch(resetAddressUpdateStatus())
            dispatch(resetAddressDeleteStatus())
        }
    }, [dispatch])

    useEffect(() => {
        if (enable2FAStatus === 'fulfilled') { setShow2FAConfirm(true); dispatch(resetEnable2FAStatus()) }
        if (enable2FAStatus === 'rejected') { toast.error(enable2FAError?.message || t('auth.profile.twoFaSendFailed')); dispatch(resetEnable2FAStatus()) }
    }, [enable2FAStatus, enable2FAError, dispatch, t])
    useEffect(() => {
        if (confirm2FAStatus === 'fulfilled') { toast.success(t('auth.profile.twoFaEnabledToast')); setShow2FAConfirm(false); dispatch(fetchLoggedInUserByIdAsync(userInfo?._id)); dispatch(checkAuthAsync()); dispatch(resetConfirm2FAStatus()) }
        if (confirm2FAStatus === 'rejected') { toast.error(confirm2FAError?.message || t('auth.login.error2faInvalid')); dispatch(resetConfirm2FAStatus()) }
    }, [confirm2FAStatus, confirm2FAError, userInfo?._id, dispatch, t])
    useEffect(() => {
        if (disable2FAStatus === 'fulfilled') { toast.success(t('auth.profile.twoFaDisabledToast')); dispatch(fetchLoggedInUserByIdAsync(userInfo?._id)); dispatch(checkAuthAsync()); dispatch(resetDisable2FAStatus()) }
        if (disable2FAStatus === 'rejected') { toast.error(disable2FAError?.message || t('auth.profile.twoFaDisableFailed')); dispatch(resetDisable2FAStatus()) }
    }, [disable2FAStatus, disable2FAError, userInfo?._id, dispatch, t])

    const handleAddAddress = (data) => {
        const address = { ...data, user: userInfo._id }
        dispatch(addAddressAsync(address))
        setAddAddress(false)
        reset()
    }

    const handleUpdateUser = (data) => {
        dispatch(updateUserByIdAsync({ _id: userInfo._id, ...data }))
    }

    const handleEnable2FA = () => { dispatch(enable2FAAsync()) }
    const handleConfirm2FA = (data) => { dispatch(confirm2FAAsync(data.otp)); reset() }
    const handleDisable2FA = () => { dispatch(disable2FAAsync()) }

    return (
        <Stack minHeight={'calc(100vh - 4rem)'} justifyContent={'flex-start'} alignItems={'center'} py={is480 ? 0 : 5}>

            <Stack component={is480 ? '' : Paper} elevation={1} width={is900 ? '100%' : "50rem"} p={is480 ? 2 : 4} rowGap={4}>

                {/* user details */}
                <Stack position="relative" bgcolor="primary.light" color="primary.main" p={4} borderRadius={'.6rem'} justifyContent={'center'} alignItems={'center'}>
                    <IconButton aria-label="edit" sx={{ position: 'absolute', top: 8, right: 8 }} onClick={() => { setIsEdit(!isEdit); resetEdit({ name: userInfo.name, email: userInfo.email, profilePicture: userInfo.profilePicture }) }}>
                        <EditIcon />
                    </IconButton>
                    <Avatar src={userInfo?.profilePicture} alt={userInfo?.name} sx={{ width: 80, height: 80, mb: 2, border: '2px solid white' }}></Avatar>

                    {!isEdit ? (
                        <>
                            <Typography variant="h5" fontWeight={600} color="text.primary">{userInfo?.name}</Typography>
                            <Typography variant="body1" color="text.secondary">{userInfo?.email}</Typography>
                        </>
                    ) : (
                        <Stack component="form" noValidate onSubmit={handleSubmitEdit(handleUpdateUser)} spacing={2} width="100%" maxWidth={400} mt={2}>
                            <TextField size="small" label={t('auth.profile.nameLabel')} {...registerEdit('name')} fullWidth />
                            <TextField size="small" label={t('auth.profile.emailLabel')} {...registerEdit('email')} fullWidth />
                            <TextField size="small" label={t('auth.profile.profilePictureLabel')} {...registerEdit('profilePicture')} fullWidth />
                            <Stack direction="row" spacing={1} justifyContent="center">
                                <LoadingButton loading={userUpdateStatus === 'pending'} type="submit" variant="contained" size="small">{t('auth.profile.saveProfile')}</LoadingButton>
                                <Button variant="outlined" size="small" color="inherit" onClick={() => setIsEdit(false)}>{t('auth.profile.cancelEdit')}</Button>
                            </Stack>
                        </Stack>
                    )}
                </Stack>

                {/* Security – Two-factor authentication */}
                <Stack p={2} borderRadius={1} border="1px solid" borderColor="divider" bgcolor="background.paper" rowGap={1}>
                    <Stack direction="row" alignItems="center" spacing={1}>
                        <SecurityIcon color="action" />
                        <Typography variant="subtitle2" fontWeight={600}>{t('auth.profile.securityTitle')}</Typography>
                    </Stack>
                    <Typography variant="body2" color="text.secondary">
                        {t('auth.profile.twoFaLabel')} <Typography component="span" fontWeight={600} color={userInfo?.twoFactorEnabled ? "success.main" : "text.secondary"}>{userInfo?.twoFactorEnabled ? t('auth.profile.twoFaOn') : t('auth.profile.twoFaOff')}</Typography>
                    </Typography>
                    {userInfo?.twoFactorEnabled ? (
                        <LoadingButton sx={{ maxWidth: 180 }} size="small" color="error" variant="outlined" loading={disable2FAStatus === 'pending'} onClick={handleDisable2FA}>{t('auth.profile.twoFaDisable')}</LoadingButton>
                    ) : (
                        <>
                            {!show2FAConfirm ? (
                                <LoadingButton sx={{ maxWidth: 180 }} size="small" variant="contained" loading={enable2FAStatus === 'pending'} onClick={handleEnable2FA}>{t('auth.profile.twoFaEnable')}</LoadingButton>
                            ) : (
                                <Stack component="form" noValidate onSubmit={handleSubmit(handleConfirm2FA)} rowGap={1} alignItems="flex-start">
                                    <Typography variant="caption" color="text.secondary">{t('auth.profile.twoFaCodeHelp')}</Typography>
                                    <TextField size="small" placeholder={t('auth.profile.twoFaCodePlaceholder')} {...register('otp', { required: true, minLength: 4 })} inputProps={{ maxLength: 8 }} sx={{ maxWidth: 160 }} />
                                    <Stack direction="row" spacing={1}>
                                        <LoadingButton size="small" type="submit" variant="contained" loading={confirm2FAStatus === 'pending'}>{t('auth.profile.twoFaConfirm')}</LoadingButton>
                                        <Button size="small" variant="outlined" onClick={() => { setShow2FAConfirm(false); dispatch(resetEnable2FAStatus()) }}>{t('auth.profile.twoFaCancel')}</Button>
                                    </Stack>
                                </Stack>
                            )}
                        </>
                    )}
                </Stack>

                {/* referral section */}
                {userInfo?.referralCode && (
                    <Stack p={2} borderRadius={1} bgcolor="action.hover" rowGap={1}>
                        <Typography variant="subtitle2" fontWeight={600}>{t('auth.referral.title')}</Typography>
                        <Typography variant="body2" color="text.secondary">{t('auth.referral.description')}</Typography>
                        <Stack direction="row" alignItems="center" spacing={1}>
                            <Typography fontFamily="monospace" fontWeight={600}>{userInfo.referralCode}</Typography>
                            <IconButton size="small" onClick={() => { navigator.clipboard.writeText(`${window.location.origin}/signup?ref=${userInfo.referralCode}`); toast.success(t('auth.referral.copied')) }}>
                                <ContentCopyIcon fontSize="small" />
                            </IconButton>
                        </Stack>
                        <Typography variant="caption" color="text.secondary">{t('auth.referral.signupLink')} {window.location.origin}/signup?ref={userInfo.referralCode}</Typography>
                    </Stack>
                )}

                {/* address section */}
                <Stack justifyContent={'center'} alignItems={'center'} rowGap={3}>


                    {/* heading and add button */}
                    <Stack flexDirection={'row'} alignItems={'center'} justifyContent={'center'} columnGap={1}>
                        <Typography variant='h6' fontWeight={400}>{t('auth.addresses.manage')}</Typography>
                        <Button onClick={() => setAddAddress(true)} size={is480 ? 'small' : ""} variant='contained'>{t('auth.addresses.add')}</Button>
                    </Stack>

                    {/* add address form - state dependent*/}
                    {
                        addAddress ? (
                            <Stack width={'100%'} component={'form'} noValidate onSubmit={handleSubmit(handleAddAddress)} rowGap={2}>

                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.type')}</Typography>
                                    <TextField placeholder={t('auth.addresses.typePlaceholder')} {...register("type", { required: true })} />
                                </Stack>


                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.street')}</Typography>
                                    <TextField {...register("street", { required: true })} />
                                </Stack>

                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.postalCode')}</Typography>
                                    <TextField type='number' {...register("postalCode", { required: true })} />
                                </Stack>

                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.country')}</Typography>
                                    <TextField {...register("country", { required: true })} />
                                </Stack>

                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.phoneNumber')}</Typography>
                                    <TextField type='number' {...register("phoneNumber", { required: true })} />
                                </Stack>

                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.state')}</Typography>
                                    <TextField {...register("state", { required: true })} />
                                </Stack>

                                <Stack>
                                    <Typography gutterBottom>{t('auth.addresses.city')}</Typography>
                                    <TextField {...register("city", { required: true })} />
                                </Stack>

                                <Stack flexDirection={'row'} alignSelf={'flex-end'} columnGap={is480 ? 1 : 2}>
                                    <LoadingButton loading={status === 'pending'} type='submit' size={is480 ? "small" : ""} variant='contained'>{t('auth.addresses.addSubmit')}</LoadingButton>
                                    <Button color='error' onClick={() => setAddAddress(false)} variant={is480 ? "outlined" : "text"} size={is480 ? "small" : ""} >{t('auth.addresses.addCancel')}</Button>
                                </Stack>
                            </Stack>
                        ) : ('')
                    }

                    {/* mapping on addresses here  */}
                    <Stack width={'100%'} rowGap={2}>
                        {
                            addresses.length > 0 ? (
                                addresses.map((address) => (
                                    <Address key={address._id} id={address._id} city={address.city} country={address.country} phoneNumber={address.phoneNumber} postalCode={address.postalCode} state={address.state} street={address.street} type={address.type} />
                                ))
                            ) : (
                                <Typography textAlign={'center'} mt={2} variant='body2'>{t('auth.addresses.noAddresses')}</Typography>
                            )
                        }
                    </Stack>

                </Stack>


            </Stack>



        </Stack>
    )
}
