import { Stack, TextField, Typography, Button, Grid, FormControl, Radio, Paper, IconButton, useTheme, useMediaQuery } from '@mui/material'
import { LoadingButton } from '@mui/lab'
import React, { useEffect, useState } from 'react'
import { Cart } from '../../cart/components/Cart'
import { useForm } from 'react-hook-form'
import { useDispatch, useSelector } from 'react-redux'
import { addAddressAsync, selectAddressStatus, selectAddresses } from '../../address/AddressSlice'
import { selectLoggedInUser } from '../../auth/AuthSlice'
import { Link, useNavigate } from 'react-router-dom'
import { createOrderAsync, selectCurrentOrder, selectOrderStatus } from '../../order/OrderSlice'
import { resetCartByUserIdAsync, selectCartItems } from '../../cart/CartSlice'
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { SHIPPING, TAXES } from '../../../constants'
import {motion} from 'framer-motion'
import { applyCouponToCartAsync, resetAppliedCoupon, selectAppliedCoupon, selectApplyCouponStatus } from '../../coupon/CouponSlice'
import { fetchMyLoyalty } from '../../admin/AdminApi'
import { createFlutterwavePayment, createFlutterwavePaymentGuest, createPayPalOrder, createPayPalOrderGuest, createStripeCheckoutSession, createStripeCheckoutSessionGuest } from '../../payment/PaymentApi'
import { axiosi } from '../../../config/axios'


export const Checkout = () => {

    const status=''
    const addresses=useSelector(selectAddresses)
    const [selectedAddress,setSelectedAddress]=useState(addresses[0])
    const [selectedPaymentMethod,setSelectedPaymentMethod]=useState('COD')
    const { register, handleSubmit, watch, reset } = useForm()
    const dispatch=useDispatch()
    const loggedInUser=useSelector(selectLoggedInUser)
    const isGuest = !loggedInUser
    const addressStatus=useSelector(selectAddressStatus)
    const navigate=useNavigate()
    const cartItems=useSelector(selectCartItems)
    const orderStatus=useSelector(selectOrderStatus)
    const currentOrder=useSelector(selectCurrentOrder)
    const orderTotal=cartItems.reduce((acc,item)=>(item.product.price*item.quantity)+acc,0)
    const theme=useTheme()
    const is900=useMediaQuery(theme.breakpoints.down(900))
    const is480=useMediaQuery(theme.breakpoints.down(480))
    const appliedCoupon=useSelector(selectAppliedCoupon)
    const applyCouponStatus=useSelector(selectApplyCouponStatus)
    const [couponCode,setCouponCode]=useState('')
    const [loyaltyBalance,setLoyaltyBalance]=useState(0)
    const [loyaltyPointsToRedeem,setLoyaltyPointsToRedeem]=useState(0)
    
    useEffect(()=>{
        if(loggedInUser){
            fetchMyLoyalty().then((d)=>setLoyaltyBalance(d.balance??0)).catch(()=>setLoyaltyBalance(0))
        }
    },[loggedInUser])

    useEffect(()=>{
        if(addressStatus==='fulfilled'){
            reset()
        }
        else if(addressStatus==='rejected'){
            alert('Error adding your address')
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- reset intentionally omitted
    },[addressStatus])

    useEffect(()=>{
        if(currentOrder && currentOrder?._id){
            dispatch(resetCartByUserIdAsync(loggedInUser?._id))
            navigate(`/order-success/${currentOrder?._id}`)
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run only when order is created
    },[currentOrder])
    
    const handleAddAddress=(data)=>{
        if(isGuest){
            setSelectedAddress(data)
            return
        }
        const address={...data,user:loggedInUser._id}
        dispatch(addAddressAsync(address))
    }

    const handleCreateOrder=()=>{
        if(!selectedAddress?._id){
            // guest address won't have _id
            if(isGuest && selectedAddress){
                // ok
            }else{
                alert('Please select an address')
                return
            }
        }

        const guestEmail = watch('guestEmail')
        const guestItems = cartItems.map((ci)=>({productId: ci.product?._id, quantity: ci.quantity}))

        // COD stays as a normal order
        if(selectedPaymentMethod==='COD'){
            if(isGuest){
                const run = async ()=>{
                    try{
                        const res = await axiosi.post('/orders/guest',{guestEmail, address:selectedAddress, items: guestItems, paymentMode:'COD'})
                        dispatch(resetCartByUserIdAsync())
                        navigate(`/payment/success?provider=cod&orderId=${res.data._id}`, { replace: true })
                    }catch(e){
                        alert('Guest order failed. Please try again.')
                    }
                }
                run()
                return
            }else{
                const order={
                    user: loggedInUser._id,
                    item: cartItems,
                    address: selectedAddress,
                    paymentMode: 'COD',
                    total: orderTotal + SHIPPING + TAXES,
                    couponCode: appliedCoupon?.code || null,
                    loyaltyPointsToRedeem: loyaltyPointsToRedeem || 0,
                }
                dispatch(createOrderAsync(order))
                return
            }
        }

        // Online payments: create payment session/order and redirect
        const addressId = selectedAddress?._id
        const run = async () => {
            try{
                if(selectedPaymentMethod==='STRIPE'){
                    const { url } = isGuest
                        ? await createStripeCheckoutSessionGuest({ guestEmail, address:selectedAddress, items: guestItems })
                        : await createStripeCheckoutSession({ addressId, couponCode: appliedCoupon?.code, loyaltyPointsToRedeem })
                    window.location.href = url
                }
                else if(selectedPaymentMethod==='PAYPAL'){
                    const { url } = isGuest
                        ? await createPayPalOrderGuest({ guestEmail, address:selectedAddress, items: guestItems })
                        : await createPayPalOrder({ addressId, couponCode: appliedCoupon?.code, loyaltyPointsToRedeem })
                    window.location.href = url
                }
                else if(selectedPaymentMethod==='MOBILE_MONEY' || selectedPaymentMethod==='ORANGE_MONEY'){
                    const { url } = isGuest
                        ? await createFlutterwavePaymentGuest({ guestEmail, address:selectedAddress, items: guestItems, method: selectedPaymentMethod })
                        : await createFlutterwavePayment({ addressId, method: selectedPaymentMethod, couponCode: appliedCoupon?.code, loyaltyPointsToRedeem })
                    window.location.href = url
                }
            }catch(e){
                alert('Payment init failed. Please try again.')
            }
        }
        run()
    }

  return (
    <Stack flexDirection={'row'} p={2} rowGap={10} justifyContent={'center'} flexWrap={'wrap'} mb={'5rem'} mt={2} columnGap={4} alignItems={'flex-start'}>

        {/* left box */}
        <Stack rowGap={4}>

            {/* heading */}
            <Stack flexDirection={'row'} columnGap={is480?0.3:1} alignItems={'center'}>
                <motion.div  whileHover={{x:-5}}>
                    <IconButton component={Link} to={"/cart"}><ArrowBackIcon fontSize={is480?"medium":'large'}/></IconButton>
                </motion.div>
                <Typography variant='h4'>Shipping Information</Typography>
            </Stack>

            {/* address form */}
            <Stack component={'form'} noValidate rowGap={2} onSubmit={handleSubmit(handleAddAddress)}>
                    {
                        isGuest &&
                        <Stack>
                            <Typography gutterBottom>Email</Typography>
                            <TextField placeholder='you@example.com' {...register("guestEmail",{required:true})}/>
                        </Stack>
                    }
                    <Stack>
                        <Typography  gutterBottom>Type</Typography>
                        <TextField placeholder='Eg. Home, Buisness' {...register("type",{required:true})}/>
                    </Stack>


                    <Stack>
                        <Typography gutterBottom>Street</Typography>
                        <TextField {...register("street",{required:true})}/>
                    </Stack>

                    <Stack>
                        <Typography gutterBottom>Country</Typography>
                        <TextField {...register("country",{required:true})}/>
                    </Stack>

                    <Stack>
                        <Typography  gutterBottom>Phone Number</Typography>
                        <TextField type='number' {...register("phoneNumber",{required:true})}/>
                    </Stack>

                    <Stack flexDirection={'row'}>
                        <Stack width={'100%'}>
                            <Typography gutterBottom>City</Typography>
                            <TextField  {...register("city",{required:true})}/>
                        </Stack>
                        <Stack width={'100%'}>
                            <Typography gutterBottom>State</Typography>
                            <TextField  {...register("state",{required:true})}/>
                        </Stack>
                        <Stack width={'100%'}>
                            <Typography gutterBottom>Postal Code</Typography>
                            <TextField type='number' {...register("postalCode",{required:true})}/>
                        </Stack>
                    </Stack>

                    <Stack flexDirection={'row'} alignSelf={'flex-end'} columnGap={1}>
                        <LoadingButton loading={status==='pending'} type='submit' variant='contained'>add</LoadingButton>
                        <Button color='error' variant='outlined' onClick={()=>reset()}>Reset</Button>
                    </Stack>
            </Stack>

            {/* existing address */}
            {
            !isGuest &&
            <Stack rowGap={3}>

                <Stack>
                    <Typography variant='h6'>Address</Typography>
                    <Typography variant='body2' color={'text.secondary'}>Choose from existing Addresses</Typography>
                </Stack>

                <Grid container gap={2} width={is900?"auto":'50rem'} justifyContent={'flex-start'} alignContent={'flex-start'}>
                        {
                            addresses.map((address,index)=>(
                                <FormControl item >
                                    <Stack key={address._id} p={is480?2:2} width={is480?'100%':'20rem'} height={is480?'auto':'15rem'}  rowGap={2} component={is480?Paper:Paper} elevation={1}>

                                        <Stack flexDirection={'row'} alignItems={'center'}>
                                            <Radio checked={selectedAddress===address} name='addressRadioGroup' value={selectedAddress} onChange={(e)=>setSelectedAddress(addresses[index])}/>
                                            <Typography>{address.type}</Typography>
                                        </Stack>

                                        {/* details */}
                                        <Stack>
                                            <Typography>{address.street}</Typography>
                                            <Typography>{address.state}, {address.city}, {address.country}, {address.postalCode}</Typography>
                                            <Typography>{address.phoneNumber}</Typography>
                                        </Stack>
                                    </Stack>
                                </FormControl>
                            ))
                        }
                </Grid>

            </Stack>
            }
            
            {/* payment methods */}
            <Stack rowGap={3}>

                    <Stack>
                        <Typography variant='h6'>Payment Methods</Typography>
                        <Typography variant='body2' color={'text.secondary'}>Please select a payment method</Typography>
                    </Stack>
                    
                    <Stack rowGap={2}>

                        <Stack flexDirection={'row'} justifyContent={'flex-start'} alignItems={'center'}>
                            <Radio value={selectedPaymentMethod} name='paymentMethod' checked={selectedPaymentMethod==='COD'} onChange={()=>setSelectedPaymentMethod('COD')}/>
                            <Typography>Cash</Typography>
                        </Stack>

                        <Stack flexDirection={'row'} justifyContent={'flex-start'} alignItems={'center'}>
                            <Radio value={selectedPaymentMethod} name='paymentMethod' checked={selectedPaymentMethod==='STRIPE'} onChange={()=>setSelectedPaymentMethod('STRIPE')}/>
                            <Typography>Card (Stripe)</Typography>
                        </Stack>

                        <Stack flexDirection={'row'} justifyContent={'flex-start'} alignItems={'center'}>
                            <Radio value={selectedPaymentMethod} name='paymentMethod' checked={selectedPaymentMethod==='PAYPAL'} onChange={()=>setSelectedPaymentMethod('PAYPAL')}/>
                            <Typography>PayPal</Typography>
                        </Stack>

                        <Stack flexDirection={'row'} justifyContent={'flex-start'} alignItems={'center'}>
                            <Radio value={selectedPaymentMethod} name='paymentMethod' checked={selectedPaymentMethod==='MOBILE_MONEY'} onChange={()=>setSelectedPaymentMethod('MOBILE_MONEY')}/>
                            <Typography>Mobile Money</Typography>
                        </Stack>
                        {(selectedPaymentMethod==='MOBILE_MONEY' || selectedPaymentMethod==='ORANGE_MONEY') && (
                            <Typography variant="body2" color="info.main" sx={{ ml: 5, mt: -1 }}>
                                You'll be redirected to complete the payment on your phone. Confirm the prompt to finish.
                            </Typography>
                        )}
                        <Stack flexDirection={'row'} justifyContent={'flex-start'} alignItems={'center'}>
                            <Radio value={selectedPaymentMethod} name='paymentMethod' checked={selectedPaymentMethod==='ORANGE_MONEY'} onChange={()=>setSelectedPaymentMethod('ORANGE_MONEY')}/>
                            <Typography>Orange Money</Typography>
                        </Stack>

                    </Stack>


            </Stack>
        </Stack>

        {/* right box */}
        <Stack  width={is900?'100%':'auto'} alignItems={is900?'flex-start':''}>
            <Typography variant='h4'>Order summary</Typography>
            <Cart checkout={true} appliedCoupon={appliedCoupon} loyaltyDiscount={(loyaltyPointsToRedeem||0)/100}/>

            {/* coupon box */}
            {
              !isGuest &&
              <Stack mt={2} width={'100%'} rowGap={1}>
                <Typography variant='body2' color={'text.secondary'}>Have a promo code?</Typography>
                <Stack flexDirection={'row'} columnGap={1} width={'100%'} flexWrap={'wrap'}>
                    <TextField
                      size='small'
                      placeholder='Enter coupon code'
                      value={couponCode}
                      onChange={(e)=>setCouponCode(e.target.value)}
                      sx={{flex:1,minWidth:'10rem'}}
                    />
                    <LoadingButton
                      size='small'
                      variant='outlined'
                      loading={applyCouponStatus==='pending'}
                      onClick={()=>dispatch(applyCouponToCartAsync(couponCode))}
                    >
                      Apply
                    </LoadingButton>
                    {
                      appliedCoupon &&
                      <Button size='small' onClick={()=>dispatch(resetAppliedCoupon())}>
                        Remove
                      </Button>
                    }
                </Stack>
                {
                  appliedCoupon &&
                  <Typography variant='body2' color={'success.main'}>
                    Coupon {appliedCoupon.code} applied: -${appliedCoupon.discount.toFixed(2)} · New total: ${appliedCoupon.total.toFixed(2)}
                  </Typography>
                }
                {!isGuest && loyaltyBalance > 0 && (
                  <Stack direction="row" alignItems="center" spacing={1} flexWrap="wrap">
                    <Typography variant="body2" color="text.secondary">Loyalty points: {loyaltyBalance} (100 pts = $1)</Typography>
                    <TextField
                      type="number"
                      size="small"
                      placeholder="Points to use"
                      value={loyaltyPointsToRedeem || ''}
                      onChange={(e)=>setLoyaltyPointsToRedeem(Math.min(Math.max(0, parseInt(e.target.value)||0), loyaltyBalance))}
                      inputProps={{ min: 0, max: loyaltyBalance }}
                      sx={{ width: 100 }}
                    />
                  </Stack>
                )}
              </Stack>
            }

            <LoadingButton fullWidth loading={orderStatus==='pending'} variant='contained' onClick={handleCreateOrder} size='large'>Pay and order</LoadingButton>
        </Stack>

    </Stack>
  )
}
