import React, { useEffect, useState } from "react"
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
  Paper,
  IconButton,
} from "@mui/material"
import RefreshIcon from "@mui/icons-material/Refresh"
import { toast } from "react-toastify"
import { fetchAdminDisputes, updateAdminDispute } from "../AdminApi"

export const AdminDisputes = () => {
  const [items, setItems] = useState([])
  const [statusFilter, setStatusFilter] = useState("")
  const [loading, setLoading] = useState(false)

  const [open, setOpen] = useState(false)
  const [selected, setSelected] = useState(null)
  const [nextStatus, setNextStatus] = useState("open")
  const [resolution, setResolution] = useState(null)
  const [notes, setNotes] = useState("")
  const [orderStatus, setOrderStatus] = useState("")

  const load = async () => {
    try {
      setLoading(true)
      const params = {}
      if (statusFilter) params.status = statusFilter
      const data = await fetchAdminDisputes(params)
      setItems(data)
    } catch (e) {
      console.error(e)
      toast.error("Error loading disputes")
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [statusFilter])

  const openDialog = (d) => {
    setSelected(d)
    setNextStatus(d.status || "open")
    setResolution(d.resolution ?? null)
    setNotes(d.notes || "")
    setOrderStatus("")
    setOpen(true)
  }

  const save = async () => {
    if (!selected) return
    try {
      const payload = { status: nextStatus, resolution, notes }
      if (orderStatus) payload.orderStatus = orderStatus
      const updated = await updateAdminDispute(selected._id, payload)
      setItems((prev) => prev.map((x) => (x._id === updated._id ? updated : x)))
      toast.success("Dispute updated")
      setOpen(false)
      setSelected(null)
    } catch (e) {
      console.error(e)
      toast.error("Error updating dispute")
    }
  }

  return (
    <Stack spacing={3}>
      <Stack direction="row" justifyContent="space-between" alignItems="center" flexWrap="wrap" rowGap={2}>
        <Stack spacing={0.5}>
          <Typography variant="h5" fontWeight={600}>
            Disputes
          </Typography>
          <Typography variant="body2" color="text.secondary">
            View and resolve buyer disputes between customers and sellers.
          </Typography>
        </Stack>
        <IconButton onClick={load} disabled={loading}>
          <RefreshIcon />
        </IconButton>
      </Stack>

      <FormControl size="small" sx={{ minWidth: 200, maxWidth: 320 }}>
        <InputLabel>Status</InputLabel>
        <Select label="Status" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
          <MenuItem value="">All</MenuItem>
          <MenuItem value="open">Open</MenuItem>
          <MenuItem value="in_review">In review</MenuItem>
          <MenuItem value="resolved">Resolved</MenuItem>
          <MenuItem value="rejected">Rejected</MenuItem>
        </Select>
      </FormControl>

      <TableContainer component={Paper}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>User</TableCell>
              <TableCell>Seller</TableCell>
              <TableCell>Order</TableCell>
              <TableCell align="center">Item</TableCell>
              <TableCell>Reason</TableCell>
              <TableCell align="center">Status</TableCell>
              <TableCell align="center">Resolution</TableCell>
              <TableCell>Created</TableCell>
              <TableCell align="right">Action</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {items.map((d) => (
              <TableRow key={d._id} hover>
                <TableCell>{d.user?.email || "-"}</TableCell>
                <TableCell>{d.seller?.email || "-"}</TableCell>
                <TableCell>{d.order?._id || d.order}</TableCell>
                <TableCell align="center">{d.itemIndex}</TableCell>
                <TableCell>{d.reason}</TableCell>
                <TableCell align="center">
                  <Chip size="small" label={d.status} variant="outlined" />
                </TableCell>
                <TableCell align="center">
                  <Chip size="small" label={d.resolution || "-"} variant="outlined" />
                </TableCell>
                <TableCell>{d.createdAt ? new Date(d.createdAt).toLocaleDateString() : "-"}</TableCell>
                <TableCell align="right">
                  <Button size="small" variant="outlined" onClick={() => openDialog(d)}>
                    Review
                  </Button>
                </TableCell>
              </TableRow>
            ))}
            {!items.length && !loading && (
              <TableRow>
                <TableCell colSpan={9}>
                  <Box py={4} textAlign="center">
                    <Typography color="text.secondary">No disputes found.</Typography>
                  </Box>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={open} onClose={() => setOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Resolve dispute</DialogTitle>
        <DialogContent>
          <Stack spacing={2} mt={1}>
            <FormControl fullWidth>
              <InputLabel>Status</InputLabel>
              <Select label="Status" value={nextStatus} onChange={(e) => setNextStatus(e.target.value)}>
                <MenuItem value="open">Open</MenuItem>
                <MenuItem value="in_review">In review</MenuItem>
                <MenuItem value="resolved">Resolved</MenuItem>
                <MenuItem value="rejected">Rejected</MenuItem>
              </Select>
            </FormControl>

            <FormControl fullWidth>
              <InputLabel>Resolution</InputLabel>
              <Select
                label="Resolution"
                value={resolution ?? ""}
                onChange={(e) => setResolution(e.target.value || null)}
              >
                <MenuItem value="">None</MenuItem>
                <MenuItem value="refund">Refund</MenuItem>
                <MenuItem value="replacement">Replacement</MenuItem>
                <MenuItem value="partial_refund">Partial refund</MenuItem>
                <MenuItem value="other">Other</MenuItem>
              </Select>
            </FormControl>

            <FormControl fullWidth>
              <InputLabel>Order status (optional)</InputLabel>
              <Select
                label="Order status (optional)"
                value={orderStatus}
                onChange={(e) => setOrderStatus(e.target.value)}
              >
                <MenuItem value="">No change</MenuItem>
                <MenuItem value="Pending">Pending</MenuItem>
                <MenuItem value="Dispatched">Dispatched</MenuItem>
                <MenuItem value="Out for delivery">Out for delivery</MenuItem>
                <MenuItem value="Delivered">Delivered</MenuItem>
                <MenuItem value="Cancelled">Cancelled</MenuItem>
              </Select>
            </FormControl>

            <TextField label="Notes" value={notes} onChange={(e) => setNotes(e.target.value)} fullWidth multiline rows={3} />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={save}>
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Stack>
  )
}

