import React from "react"
import { Button, Paper, Stack, Typography } from "@mui/material"
import { Link, useSearchParams } from "react-router-dom"
import { useSelector } from "react-redux"
import { selectLoggedInUser } from "../features/auth/AuthSlice"
import { useTranslation } from "react-i18next"

const getProviderLabel = (p, t) => {
  if (p === "cod") return t("payment.providerCod", "Cash on delivery")
  if (p === "mobile_money" || p === "MOBILE_MONEY") return t("payment.providerMobileMoney", "Mobile Money")
  if (p === "orange_money" || p === "ORANGE_MONEY") return t("payment.providerOrangeMoney", "Orange Money")
  if (p === "stripe") return t("payment.providerStripe", "Card (Stripe)")
  if (p === "paypal") return t("payment.providerPaypal", "PayPal")
  return p
}

export const PaymentSuccessPage = () => {
  const [params] = useSearchParams()
  const provider = params.get("provider")
  const orderId = params.get("orderId")
  const status = params.get("status") || "success"
  const loggedInUser = useSelector(selectLoggedInUser)
  const { t } = useTranslation()

  const isMobileMoney = ["mobile_money", "MOBILE_MONEY", "orange_money", "ORANGE_MONEY"].includes(provider)
  const isPending = status === "pending"

  return (
    <Stack width="100vw" height="100vh" justifyContent="center" alignItems="center" p={2}>
      <Paper elevation={2} sx={{ p: 3, maxWidth: 520, width: "100%" }}>
        <Stack rowGap={2}>
          <Typography variant="h5" fontWeight={600}>
            {isPending && isMobileMoney
              ? t("payment.completeOnPhone")
              : isPending
                ? t("payment.processing")
                : t("payment.received")}
          </Typography>
          <Typography color="text.secondary">
            {isPending && isMobileMoney
              ? t("payment.completeOnPhoneDesc")
              : isPending
                ? t("payment.processingDesc", {
                    provider: getProviderLabel(provider, t) || t("payment.generic", "payment"),
                  })
                : provider
                  ? t("payment.paidVia", { provider: getProviderLabel(provider, t) })
                  : t("payment.received")}
          </Typography>

          {orderId && loggedInUser && (
            <Button component={Link} to={`/order-success/${orderId}`} variant="contained">
              {t("payment.viewOrder")}
            </Button>
          )}

          {loggedInUser && (
            <Button component={Link} to={"/orders"} variant="outlined">
              {t("payment.goToOrders")}
            </Button>
          )}
        </Stack>
      </Paper>
    </Stack>
  )
}

