import React, { useEffect, useState, useRef } from "react"
import { useSelector } from "react-redux"
import { selectLoggedInUser } from "../features/auth/AuthSlice"
import {
  Box, Divider, Paper, Stack, TextField, Typography,
  Avatar, IconButton, Badge, alpha, useTheme, Button,
  Tooltip, CircularProgress
} from "@mui/material"
import { SellerLayout } from "../layouts/SellerLayout"
import {
  fetchSellerConversations,
  fetchSellerConversationMessages,
  sendSellerMessage,
} from "../features/seller/SellerApi"
import { LoadingButton } from "@mui/lab"
import { toast } from "react-toastify"
import SearchIcon from '@mui/icons-material/Search'
import SendIcon from '@mui/icons-material/Send'
import MoreVertIcon from '@mui/icons-material/MoreVert'
import PhoneIcon from '@mui/icons-material/Phone'
import VideoCallIcon from '@mui/icons-material/VideoCall'
import InfoIcon from '@mui/icons-material/Info'
import ChatIcon from '@mui/icons-material/Chat'
import MarkEmailReadIcon from '@mui/icons-material/MarkEmailRead'

export const SellerInboxPage = () => {
  const theme = useTheme()
  const loggedInUser = useSelector(selectLoggedInUser)
  const [conversations, setConversations] = useState([])
  const [selected, setSelected] = useState(null)
  const [messages, setMessages] = useState([])
  const [newMessage, setNewMessage] = useState("")
  const [loading, setLoading] = useState(true)
  const [messagesLoading, setMessagesLoading] = useState(false)
  const [sendLoading, setSendLoading] = useState(false)
  const [searchQuery, setSearchQuery] = useState("")

  const messagesEndRef = useRef(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" })
  }

  const loadConversations = async () => {
    setLoading(true)
    try {
      const data = await fetchSellerConversations()
      setConversations(data)
    } catch (e) {
      toast.error("Error loading conversations")
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadConversations()
  }, [])

  useEffect(() => {
    if (!selected) {
      setMessages([])
      return
    }
    setMessagesLoading(true)
    fetchSellerConversationMessages(selected._id)
      .then(data => {
        setMessages(data)
        setTimeout(scrollToBottom, 100)
      })
      .catch(() => toast.error("Error loading chat history"))
      .finally(() => setMessagesLoading(false))
  }, [selected])

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSend = async () => {
    const body = String(newMessage || "").trim()
    if (!body || !selected) return
    setSendLoading(true)
    try {
      const msg = await sendSellerMessage(selected._id, body)
      setMessages((prev) => [...prev, msg])
      setNewMessage("")
      loadConversations() // Update last message in list
    } catch (e) {
      toast.error("Message delivery failed")
    } finally {
      setSendLoading(false)
    }
  }

  const filteredConversations = conversations.filter(c =>
    c.buyer?.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.buyer?.email?.toLowerCase().includes(searchQuery.toLowerCase())
  )

  return (
    <SellerLayout>
      <Stack spacing={4} sx={{ height: 'calc(100vh - 180px)' }}>
        {/* Header */}
        <Box>
          <Typography variant="h4" fontWeight={800} sx={{ letterSpacing: -1 }}>
            Customer Support Inbox
          </Typography>
          <Typography variant="body1" color="text.secondary">
            Direct communication with your buyers regarding orders and inquiries.
          </Typography>
        </Box>

        {/* Main Interface */}
        <Box sx={{
          display: "flex",
          flex: 1,
          bgcolor: 'background.paper',
          borderRadius: 4,
          border: '1px solid',
          borderColor: 'divider',
          overflow: 'hidden',
          boxShadow: '0 4px 20px rgba(0,0,0,0.03)'
        }}>
          {/* Conversation List */}
          <Box sx={{
            width: { xs: '100%', sm: 320, md: 380 },
            borderRight: '1px solid',
            borderColor: 'divider',
            display: 'flex',
            flexDirection: 'column'
          }}>
            <Box sx={{ p: 2 }}>
              <Box sx={{
                display: 'flex', alignItems: 'center',
                bgcolor: 'action.hover', borderRadius: 3, px: 2, py: 1
              }}>
                <SearchIcon sx={{ color: 'text.secondary', mr: 1, fontSize: 20 }} />
                <TextField
                  variant="standard"
                  placeholder="Search conversations..."
                  fullWidth
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  InputProps={{ disableUnderline: true, sx: { fontSize: '0.9rem' } }}
                />
              </Box>
            </Box>

            <Divider />

            <Box sx={{ flex: 1, overflow: 'auto' }}>
              {loading ? (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}><CircularProgress size={24} /></Box>
              ) : filteredConversations.length === 0 ? (
                <Box sx={{ p: 4, textAlign: 'center' }}>
                  <Typography variant="body2" color="text.secondary">No conversations found</Typography>
                </Box>
              ) : (
                filteredConversations.map((c) => (
                  <Box
                    key={c._id}
                    onClick={() => setSelected(c)}
                    sx={{
                      p: 2.5,
                      cursor: "pointer",
                      transition: 'all 0.2s',
                      borderBottom: '1px solid',
                      borderColor: alpha(theme.palette.divider, 0.5),
                      bgcolor: selected?._id === c._id ? alpha(theme.palette.primary.main, 0.05) : "transparent",
                      borderLeft: '4px solid',
                      borderLeftColor: selected?._id === c._id ? 'primary.main' : 'transparent',
                      "&:hover": { bgcolor: selected?._id === c._id ? alpha(theme.palette.primary.main, 0.08) : 'action.hover' },
                    }}
                  >
                    <Stack direction="row" spacing={2} alignItems="center">
                      <Badge
                        overlap="circle"
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                        variant="dot"
                        color="success"
                      >
                        <Avatar sx={{ bgcolor: alpha(theme.palette.secondary.main, 0.1), color: 'secondary.main', fontWeight: 800 }}>
                          {c.buyer?.name?.[0].toUpperCase() || "U"}
                        </Avatar>
                      </Badge>
                      <Box sx={{ flex: 1, overflow: 'hidden' }}>
                        <Stack direction="row" justifyContent="space-between" alignItems="center">
                          <Typography variant="body2" fontWeight={800} noWrap sx={{ maxWidth: 150 }}>
                            {c.buyer?.name || "Customer"}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            {c.lastMessage?.createdAt ? new Date(c.lastMessage.createdAt).toLocaleDateString([], { month: 'short', day: 'numeric' }) : ""}
                          </Typography>
                        </Stack>
                        <Typography variant="caption" color="text.secondary" noWrap display="block" sx={{ mt: 0.5 }}>
                          {c.lastMessage?.body || "Start a conversation..."}
                        </Typography>
                      </Box>
                    </Stack>
                  </Box>
                ))
              )}
            </Box>
          </Box>

          {/* Chat Window */}
          <Box sx={{ flex: 1, display: "flex", flexDirection: "column", bgcolor: alpha(theme.palette.action.hover, 0.2) }}>
            {!selected ? (
              <Stack flex={1} justifyContent="center" alignItems="center" spacing={2} sx={{ opacity: 0.5 }}>
                <ChatIcon sx={{ fontSize: 64 }} />
                <Typography variant="h6" fontWeight={700}>Select a conversation to start chatting</Typography>
                <Typography variant="body2">Customer messages regarding orders will appear here.</Typography>
              </Stack>
            ) : (
              <>
                {/* Chat Header */}
                <Box sx={{ p: 2, px: 3, borderBottom: 1, borderColor: "divider", bgcolor: 'background.paper', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Stack direction="row" spacing={2} alignItems="center">
                    <Avatar sx={{ bgcolor: alpha(theme.palette.secondary.main, 0.1), color: 'secondary.main' }}>
                      {selected.buyer?.name?.[0].toUpperCase() || "U"}
                    </Avatar>
                    <Box>
                      <Typography variant="body1" fontWeight={800}>
                        {selected.buyer?.name || "Customer"}
                      </Typography>
                      <Typography variant="caption" color="text.secondary" sx={{ display: 'flex', alignItems: 'center' }}>
                        <Box sx={{ width: 8, height: 8, borderRadius: '50%', bgcolor: 'success.main', mr: 1 }} />
                        Active · {selected.buyer?.email}
                      </Typography>
                    </Box>
                  </Stack>
                  <Stack direction="row" spacing={1}>
                    <Tooltip title="Call"><IconButton size="small"><PhoneIcon fontSize="small" /></IconButton></Tooltip>
                    <Tooltip title="Order Info"><IconButton size="small"><InfoIcon fontSize="small" /></IconButton></Tooltip>
                    <Tooltip title="Options"><IconButton size="small"><MoreVertIcon fontSize="small" /></IconButton></Tooltip>
                  </Stack>
                </Box>

                {/* Messages Area */}
                <Box sx={{ flex: 1, overflow: "auto", p: 3, display: 'flex', flexDirection: 'column' }}>
                  {messagesLoading ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}><CircularProgress size={24} /></Box>
                  ) : (
                    <Stack spacing={2.5}>
                      {messages.map((m) => {
                        const isMe = String(m.sender?._id) === String(loggedInUser?._id)
                        return (
                          <Box
                            key={m._id}
                            sx={{
                              alignSelf: isMe ? "flex-end" : "flex-start",
                              maxWidth: "70%",
                              display: 'flex',
                              flexDirection: 'column',
                              alignItems: isMe ? 'flex-end' : 'flex-start'
                            }}
                          >
                            <Box sx={{
                              p: 2,
                              px: 2.5,
                              borderRadius: isMe ? '20px 20px 4px 20px' : '20px 20px 20px 4px',
                              bgcolor: isMe ? 'primary.main' : 'background.paper',
                              color: isMe ? 'white' : 'text.primary',
                              boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
                              border: isMe ? 'none' : '1px solid',
                              borderColor: 'divider'
                            }}>
                              <Typography variant="body2">{m.body}</Typography>
                            </Box>
                            <Typography variant="caption" sx={{ mt: 0.5, color: 'text.secondary', fontSize: '10px', px: 1 }}>
                              {new Date(m.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              {isMe && <MarkEmailReadIcon sx={{ fontSize: 12, ml: 0.5, verticalAlign: 'middle', color: 'primary.main' }} />}
                            </Typography>
                          </Box>
                        )
                      })}
                      <div ref={messagesEndRef} />
                    </Stack>
                  )}
                </Box>

                {/* Message Input */}
                <Box sx={{ p: 2.5, bgcolor: 'background.paper', borderTop: 1, borderColor: 'divider' }}>
                  <Stack direction="row" spacing={1.5} alignItems="center">
                    <TextField
                      fullWidth
                      multiline
                      maxRows={4}
                      placeholder="Write your message here..."
                      value={newMessage}
                      onChange={(e) => setNewMessage(e.target.value)}
                      onKeyDown={(e) => e.key === "Enter" && !e.shiftKey && (e.preventDefault(), handleSend())}
                      disabled={sendLoading}
                      sx={{
                        '& .MuiOutlinedInput-root': {
                          borderRadius: 4,
                          bgcolor: alpha(theme.palette.action.hover, 0.5),
                          px: 2
                        }
                      }}
                    />
                    <LoadingButton
                      loading={sendLoading}
                      variant="contained"
                      onClick={handleSend}
                      sx={{
                        borderRadius: '50%',
                        minWidth: 48,
                        width: 48,
                        height: 48,
                        boxShadow: theme.shadows[4]
                      }}
                    >
                      {!sendLoading && <SendIcon />}
                    </LoadingButton>
                  </Stack>
                </Box>
              </>
            )}
          </Box>
        </Box>
      </Stack>
    </SellerLayout>
  )
}
