import * as React from 'react';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';
import Menu from '@mui/material/Menu';
import Avatar from '@mui/material/Avatar';
import Tooltip from '@mui/material/Tooltip';
import MenuItem from '@mui/material/MenuItem';
import InputBase from '@mui/material/InputBase';
import SearchIcon from '@mui/icons-material/Search';
import { Link, useNavigate } from 'react-router-dom';
import { Badge, Button, Chip, Stack, useMediaQuery, useTheme } from '@mui/material';
import DarkModeIcon from '@mui/icons-material/DarkMode';
import LightModeIcon from '@mui/icons-material/LightMode';
import { useThemeMode } from '../../../context/ThemeModeContext';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import { selectUserInfo } from '../../user/UserSlice';
import ShoppingCartOutlinedIcon from '@mui/icons-material/ShoppingCartOutlined';
import { selectCartItems } from '../../cart/CartSlice';
import { selectLoggedInUser } from '../../auth/AuthSlice';
import { selectWishlistItems } from '../../wishlist/WishlistSlice';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import TuneIcon from '@mui/icons-material/Tune';
import { selectProductIsFilterOpen, toggleFilters } from '../../products/ProductSlice';
import { selectSellerProfile } from '../../seller/SellerSlice';




export const Navbar = ({ isProductList = false, searchQuery, onSearchChange }) => {
  const [anchorElUser, setAnchorElUser] = React.useState(null);
  const userInfo = useSelector(selectUserInfo)
  const cartItems = useSelector(selectCartItems)
  const loggedInUser = useSelector(selectLoggedInUser)
  const navigate = useNavigate()
  const dispatch = useDispatch()
  const theme = useTheme()
  const is480 = useMediaQuery(theme.breakpoints.down(480))
  const { mode, toggleMode, fontScale, setFontSize } = useThemeMode()
  const { t, i18n } = useTranslation()

  const wishlistItems = useSelector(selectWishlistItems)
  const isProductFilterOpen = useSelector(selectProductIsFilterOpen)
  const sellerProfile = useSelector(selectSellerProfile)


  const handleOpenUserMenu = (event) => {
    setAnchorElUser(event.currentTarget);
  };

  const handleCloseUserMenu = () => {
    setAnchorElUser(null);
  };

  const handleToggleFilters = () => {
    dispatch(toggleFilters())
  }

  const settings = [
    { name: t('common.home'), to: "/" },
    { name: t('common.profile'), to: "/profile" },
    { name: t('common.orders'), to: "/orders" },
    ...(loggedInUser?.role === 'seller' || sellerProfile?.status === 'approved'
      ? [{ name: t('common.sellerDashboard'), to: "/seller/dashboard" }]
      : loggedInUser?.role !== 'admin'
        ? [{ name: t('common.becomeSeller'), to: "/seller/apply" }]
        : []
    ),

    { name: t('common.logout'), to: "/logout" },
  ];

  return (
    <AppBar position="sticky" sx={{ backgroundColor: "background.paper", boxShadow: "none", color: "text.primary", borderBottom: mode === 'dark' ? '1px solid rgba(255,255,255,0.12)' : '1px solid rgba(0,0,0,0.12)' }}>
      <Toolbar sx={{ p: 1, height: "4rem", display: "flex", justifyContent: "space-around" }}>

        <Typography variant="h6" noWrap component="a" href="/" sx={{ mr: 2, display: { xs: 'none', md: 'flex' }, fontWeight: 700, letterSpacing: '.3rem', color: 'inherit', textDecoration: 'none', }}>
          {t('auth.login.title')}
        </Typography>

        {isProductList && (
          <Stack
            direction="row"
            sx={{
              flex: 1,
              maxWidth: 400,
              mx: 2,
              display: { xs: 'none', sm: 'flex' },
              alignItems: 'center',
              bgcolor: 'action.hover',
              borderRadius: 1,
              px: 1.5,
              py: 0.5,
            }}
          >
            <SearchIcon sx={{ color: 'text.secondary', mr: 1 }} />
            <InputBase
              placeholder={t('common.search')}
              value={searchQuery || ''}
              onChange={(e) => onSearchChange?.(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') e.preventDefault();
              }}
              sx={{ flex: 1, fontSize: '0.95rem', color: 'text.primary' }}
            />
          </Stack>
        )}
        <Stack flexDirection={'row'} alignItems={'center'} justifyContent={'center'} columnGap={2}>
          <Tooltip title="Open settings">
            <IconButton onClick={handleOpenUserMenu} sx={{ p: 0 }}>
              <Avatar alt={userInfo?.name} src={userInfo?.profilePicture || "null"} />
            </IconButton>
          </Tooltip>
          <Menu
            sx={{ mt: '45px' }}
            id="menu-appbar"
            anchorEl={anchorElUser}
            anchorOrigin={{
              vertical: 'top',
              horizontal: 'right',
            }}
            keepMounted
            transformOrigin={{
              vertical: 'top',
              horizontal: 'right',
            }}
            open={Boolean(anchorElUser)}
            onClose={handleCloseUserMenu}
          >

            {
              loggedInUser?.role === 'admin' &&
              <MenuItem onClick={handleCloseUserMenu} component={Link} to="/admin/add-product">
                <Typography color={'text.primary'} sx={{ textDecoration: "none" }} textAlign="center">{t('common.addNewProduct')}</Typography>
              </MenuItem>
            }
            <MenuItem onClick={(e) => e.stopPropagation()}>
              <Stack direction="row" alignItems="center" spacing={1}>
                <Typography variant="body2">{t('common.textSize')}</Typography>
                {["small", "medium", "large"].map((s) => (
                  <Chip key={s} size="small" label={s} onClick={(e) => { e.stopPropagation(); setFontSize(s) }} color={fontScale === s ? "primary" : "default"} variant={fontScale === s ? "filled" : "outlined"} />
                ))}
              </Stack>
            </MenuItem>
            {settings.map((setting) => (
              <MenuItem key={setting.to} component={Link} to={setting.to} onClick={handleCloseUserMenu}>
                <Typography color={'text.primary'} sx={{ textDecoration: "none" }} textAlign="center">{setting.name}</Typography>
              </MenuItem>
            ))}
          </Menu>
          <Stack>
            <Typography variant='h6' fontWeight={300} color="text.primary" sx={{ lineHeight: 1.2 }}>
              {is480 ? `${userInfo?.name?.toString().split(" ")[0] || ''}` : `Hey👋, ${userInfo?.name || ''}`}
            </Typography>
            <Typography variant='caption' color="text.secondary" sx={{ mt: -0.5 }}>
              {t('common.role', { role: t(`common.roles.${sellerProfile?.status === 'approved' ? 'seller' : (loggedInUser?.role || 'buyer')}`) })}
            </Typography>

          </Stack>
          {loggedInUser?.role === 'admin' && <Button variant='contained' onClick={() => navigate('/admin/dashboard')}>{t('common.admin')}</Button>}
          <Stack sx={{ flexDirection: "row", columnGap: "1rem", alignItems: "center", justifyContent: "center" }}>

            <Stack direction="row" alignItems="center" spacing={0.5}>
              <Chip size="small" label="EN" onClick={() => i18n.changeLanguage('en')} color={i18n.language === 'en' ? 'primary' : 'default'} variant={i18n.language === 'en' ? "filled" : "outlined"} sx={{ minWidth: 36 }} />
              <Chip size="small" label="FR" onClick={() => i18n.changeLanguage('fr')} color={i18n.language === 'fr' ? 'primary' : 'default'} variant={i18n.language === 'fr' ? "filled" : "outlined"} sx={{ minWidth: 36 }} />
            </Stack>
            <IconButton onClick={toggleMode} size="small" title={mode === 'dark' ? 'Light mode' : 'Dark mode'} sx={{ color: 'text.primary' }}>
              {mode === 'dark' ? <LightModeIcon /> : <DarkModeIcon />}
            </IconButton>
            {
              cartItems?.length > 0 &&
              <Badge badgeContent={cartItems.length} color='error'>
                <IconButton onClick={() => navigate("/cart")} sx={{ color: 'text.primary' }}>
                  <ShoppingCartOutlinedIcon />
                </IconButton>
              </Badge>
            }

            {
              loggedInUser?.role !== 'admin' &&
              <Stack>
                <Badge badgeContent={wishlistItems?.length} color='error'>
                  <IconButton component={Link} to={"/wishlist"} sx={{ color: 'text.primary' }}><FavoriteBorderIcon /></IconButton>
                </Badge>
              </Stack>
            }
            {
              isProductList && <IconButton onClick={handleToggleFilters} sx={{ color: 'text.primary' }}><TuneIcon sx={{ color: isProductFilterOpen ? "primary.main" : "text.primary" }} /></IconButton>
            }

          </Stack>
        </Stack>
      </Toolbar>
    </AppBar>
  );
}
