import React, { useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { getOrderByUserIdAsync, resetOrderFetchStatus, selectOrderFetchStatus, selectOrders } from '../OrderSlice'
import { selectLoggedInUser } from '../../auth/AuthSlice'
import { Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, Paper, Stack, TextField, Typography, useMediaQuery, useTheme } from '@mui/material'
import { LoadingButton } from '@mui/lab'
import { Link } from 'react-router-dom'
import { addToCartAsync, resetCartItemAddStatus, selectCartItemAddStatus, selectCartItems } from '../../cart/CartSlice'
import Lottie from 'lottie-react'
import { loadingAnimation, noOrdersAnimation } from '../../../assets'
import { toast } from 'react-toastify'
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { motion } from 'framer-motion'
import { createReturnRequest, createDispute } from '../../admin/AdminApi'
import { sendMessageToSeller } from '../../seller/SellerApi'


export const UserOrders = () => {

    const dispatch = useDispatch()
    const loggedInUser = useSelector(selectLoggedInUser)
    const orders = useSelector(selectOrders)
    const cartItems = useSelector(selectCartItems)
    const orderFetchStatus = useSelector(selectOrderFetchStatus)

    const theme = useTheme()
    const is1200 = useMediaQuery(theme.breakpoints.down("1200"))
    const is768 = useMediaQuery(theme.breakpoints.down("768"))
    const is660 = useMediaQuery(theme.breakpoints.down(660))
    const is480 = useMediaQuery(theme.breakpoints.down("480"))

    const cartItemAddStatus = useSelector(selectCartItemAddStatus)

    useEffect(() => {
        window.scrollTo({
            top: 0,
            behavior: "instant"
        })
    }, [])

    useEffect(() => {
        dispatch(getOrderByUserIdAsync(loggedInUser?._id))
    }, [dispatch, loggedInUser?._id])


    useEffect(() => {

        if (cartItemAddStatus === 'fulfilled') {
            toast.success("Product added to cart")
        }

        else if (cartItemAddStatus === 'rejected') {
            toast.error('Error adding product to cart, please try again later')
        }
    }, [cartItemAddStatus])

    useEffect(() => {
        if (orderFetchStatus === 'rejected') {
            toast.error("Error fetching orders, please try again later")
        }
    }, [orderFetchStatus])

    useEffect(() => {
        return () => {
            dispatch(resetOrderFetchStatus())
            dispatch(resetCartItemAddStatus())
        }
    }, [dispatch])


    const handleAddToCart = (product) => {
        const item = { user: loggedInUser._id, product: product._id, quantity: 1 }
        dispatch(addToCartAsync(item))
    }

    const handleRequestReturn = async (orderId, itemIndex) => {
        const reason = window.prompt("Why are you requesting a return? (e.g. wrong size, damaged, not as described)")
        if (!reason) return
        try {
            await createReturnRequest({ orderId, itemIndex, reason })
            toast.success("Return request submitted")
        } catch (error) {
            console.log(error)
            toast.error("Error submitting return request")
        }
    }

    const handleOpenDispute = async (orderId, itemIndex) => {
        const reason = window.prompt("Describe the issue with this item (e.g. wrong item, never arrived, seller issue)")
        if (!reason) return
        try {
            await createDispute({ orderId, itemIndex, reason })
            toast.success("Dispute opened")
        } catch (error) {
            console.log(error)
            toast.error("Error opening dispute")
        }
    }

    const [messageSellerOpen, setMessageSellerOpen] = React.useState(false)
    const [messageSellerTarget, setMessageSellerTarget] = React.useState({ sellerId: null, orderId: null })
    const [messageBody, setMessageBody] = React.useState("")
    const [messageSending, setMessageSending] = React.useState(false)

    const handleOpenMessageSeller = (sellerId, orderId) => {
        setMessageSellerTarget({ sellerId, orderId })
        setMessageBody("")
        setMessageSellerOpen(true)
    }

    const handleSendMessageToSeller = async () => {
        const body = String(messageBody || "").trim()
        if (!body || !messageSellerTarget.sellerId) return
        setMessageSending(true)
        try {
            await sendMessageToSeller(messageSellerTarget.sellerId, body, messageSellerTarget.orderId)
            toast.success("Message sent")
            setMessageSellerOpen(false)
        } catch (e) {
            toast.error("Error sending message")
        } finally {
            setMessageSending(false)
        }
    }

    return (
        <Stack justifyContent={'center'} alignItems={'center'}>
            {
                orderFetchStatus === 'pending' ?
                    <Stack width={is480 ? 'auto' : '25rem'} height={'calc(100vh - 4rem)'} justifyContent={'center'} alignItems={'center'}>
                        <Lottie animationData={loadingAnimation} />
                    </Stack>
                    :
                    <Stack width={is1200 ? "auto" : "60rem"} p={is480 ? 2 : 4} mb={'5rem'}>

                        {/* heading and navigation */}
                        <Stack flexDirection={'row'} columnGap={2} >
                            {
                                !is480 && <motion.div whileHover={{ x: -5 }} style={{ alignSelf: "center" }}>
                                    <IconButton component={Link} to={"/"}><ArrowBackIcon fontSize='large' /></IconButton>
                                </motion.div>
                            }


                            <Stack rowGap={1} >
                                <Typography variant='h4' fontWeight={500}>Order history</Typography>
                                <Typography sx={{ wordWrap: "break-word" }} color={'text.secondary'}>Check the status of recent orders, manage returns, and discover similar products.</Typography>
                            </Stack>

                        </Stack>

                        {/* orders */}
                        <Stack mt={5} rowGap={5}>

                            {/* orders mapping */}
                            {
                                orders && orders.map((order) => (
                                    <Stack p={is480 ? 0 : 2} component={is480 ? "" : Paper} elevation={1} rowGap={2}>

                                        {/* upper */}
                                        <Stack flexDirection={'row'} rowGap={'1rem'} justifyContent={'space-between'} flexWrap={'wrap'}>
                                            <Stack flexDirection={'row'} columnGap={4} rowGap={'1rem'} flexWrap={'wrap'}>
                                                <Stack>
                                                    <Typography>Order Number</Typography>
                                                    <Typography color={'text.secondary'}>{order._id}</Typography>
                                                </Stack>

                                                <Stack>
                                                    <Typography>Date Placed</Typography>
                                                    <Typography color={'text.secondary'}>{new Date(order.createdAt).toDateString()}</Typography>
                                                </Stack>

                                                <Stack>
                                                    <Typography>Total Amount</Typography>
                                                    <Typography>${order.total}</Typography>
                                                </Stack>
                                            </Stack>

                                            <Stack>
                                                <Typography>Item: {order.item.length}</Typography>
                                            </Stack>
                                        </Stack>

                                        {/* middle */}
                                        <Stack rowGap={2}>

                                            {
                                                order.item.map((product, idx) => (

                                                    <Stack mt={2} flexDirection={'row'} rowGap={is768 ? '2rem' : ''} columnGap={4} flexWrap={is768 ? "wrap" : "nowrap"}>

                                                        <Stack>
                                                            <img style={{ width: "100%", aspectRatio: is480 ? 3 / 2 : 1 / 1, objectFit: "contain" }} src={product.product.images[0]} alt="" />
                                                        </Stack>

                                                        <Stack rowGap={1} width={'100%'}>

                                                            <Stack flexDirection={'row'} justifyContent={'space-between'}>
                                                                <Stack>
                                                                    <Typography variant='h6' fontSize={'1rem'} fontWeight={500}>{product.product.title}</Typography>
                                                                    <Typography variant='body1' fontSize={'.9rem'} color={'text.secondary'}>{product.product.brand.name}</Typography>
                                                                    <Typography color={'text.secondary'} fontSize={'.9rem'}>Qty: {product.quantity}</Typography>
                                                                </Stack>
                                                                <Typography>${product.product.price}</Typography>
                                                            </Stack>

                                                            <Typography color={'text.secondary'}>{product.product.shortDescription}</Typography>

                                                            <Stack mt={2} alignSelf={is480 ? "flex-start" : 'flex-end'} flexDirection={'row'} columnGap={2} >
                                                                <Button size='small' component={Link} to={`/product-details/${product.product._id}`} variant='outlined'>View Product</Button>
                                                                {
                                                                    cartItems.some((cartItem) => cartItem.product._id === product.product._id) ?
                                                                        <Button size='small' variant='contained' component={Link} to={"/cart"}>Already in Cart</Button>
                                                                        : <Button size='small' variant='contained' onClick={() => handleAddToCart(product.product)}>Buy Again</Button>
                                                                }
                                                                <Button size='small' color='warning' variant='outlined' onClick={() => handleRequestReturn(order._id, idx)}>
                                                                    Request return
                                                                </Button>
                                                                <Button size='small' color='error' variant='outlined' onClick={() => handleOpenDispute(order._id, idx)}>
                                                                    Open dispute
                                                                </Button>
                                                                {product.product?.seller && (
                                                                    <Button size='small' variant='outlined' onClick={() => handleOpenMessageSeller(product.product.seller._id || product.product.seller, order._id)}>
                                                                        Message seller
                                                                    </Button>
                                                                )}
                                                            </Stack>

                                                        </Stack>



                                                    </Stack>
                                                ))
                                            }

                                        </Stack>

                                        {/* lower */}
                                        <Stack mt={2} flexDirection={'row'} justifyContent={'space-between'}>
                                            <Stack>
                                                <Typography>Order status : {order.status}</Typography>
                                                {order.paymentStatus && <Typography mb={2}>Payment : {order.paymentStatus}</Typography>}
                                            </Stack>
                                        </Stack>

                                    </Stack>
                                ))

                            }

                            {/* no orders animation */}
                            {
                                !orders.length &&
                                <Stack mt={is480 ? '2rem' : 0} mb={'7rem'} alignSelf={'center'} rowGap={2}>

                                    <Stack width={is660 ? "auto" : '30rem'} height={is660 ? "auto" : '30rem'}>
                                        <Lottie animationData={noOrdersAnimation} />
                                    </Stack>

                                    <Typography textAlign={'center'} alignSelf={'center'} variant='h6' >oh! Looks like you haven't been shopping lately</Typography>

                                </Stack>
                            }

                        </Stack>

                    </Stack>

            }

            <Dialog open={messageSellerOpen} onClose={() => setMessageSellerOpen(false)} maxWidth="sm" fullWidth>
                <DialogTitle>Message seller</DialogTitle>
                <DialogContent>
                    <TextField
                        fullWidth
                        multiline
                        rows={3}
                        label="Your message"
                        value={messageBody}
                        onChange={(e) => setMessageBody(e.target.value)}
                        placeholder="Ask a question about your order…"
                        sx={{ mt: 1 }}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setMessageSellerOpen(false)}>Cancel</Button>
                    <LoadingButton variant="contained" onClick={handleSendMessageToSeller} disabled={!messageBody.trim()} loading={messageSending}>
                        Send
                    </LoadingButton>
                </DialogActions>
            </Dialog>
        </Stack>
    )
}
